rative": "As in forbid, but the source supplies no lane ordinals or counts (st.lane_adjacency absent).", "masked": ["st.lane_adjacency"]}, {"name": "branch_1", "expected": "violated", "narrative": "As in permit, but within r the subject drifts so that its footprint overlaps both lanes for several scenes before the exit."}], "occasion": {"act": "drv.motion.right_turn_through_region", "boundary": "event", "onset": {"words": "the operation of vehicles within a roundabout", "atoms": ["rel.occupies", "st.roundabout"], "derived": [], "justification": "The act begins at the subject's entry into the roundabout: the observation at which rel.occupies(subject, r) rose, the onset the concept declares."}, "recognition": "who intends to exit a roundabout", "under_way": {"words": "to turn right", "atoms": ["kin.yaw_rate", "rel.occupies", "st.roundabout"], "derived": [], "justification": "Inside the act the subject's heading change since its entry into r (headingSince, integrated from kin.yaw_rate \"rate of change of heading\") is defined and its footprint overlaps r; before the entry it is not."}, "spans": {"s4": "at_recognition"}}, "literals": [], "param_proposals": [{"name": "p.turn_heading_min", "unit": "deg", "value": 45.0, "convention": "the smallest heading change over the turn window at which a change of course counts as a turn rather than a lane change or a drift", "source": "turning-movement classification in intersection geometric design practice (AASHTO, A Policy on Geometric Design of Highways and Streets)"}, {"name": "p.u_turn_heading_min", "unit": "deg", "value": 135.0, "convention": "the smallest heading change magnitude over the turn window at which a turn counts as a reversal of direction", "source": "turning-movement classification in intersection geometric design practice (AASHTO, A Policy on Geometric Design of Highways and Streets)"}], "gaps": [], "gap_resolutions": []}

